bool mover(int*& actual, int* inicio, int pasos) {
    // Construye los limites y aplica solo los desplazamientos aceptados.

    return pasos == 0 && actual == inicio;
}

bool situar(int*& actual, int* inicio, int indice) {
    if (indice < 0 || indice > 4) {
        return false;
    }
    actual = inicio + indice;
    return true;
}

std::string escribir(int* actual, int* fin, int valor) {
    if (actual == fin) {
        return "Fin";
    }
    if (valor < 0 || valor > 9) {
        return "Rechazo";
    }
    *actual = valor;
    return "Cambio";
}

int main() {
    std::array<int, 4> datos{2, 5, 8, 1};
    int* inicio = datos.data();
    int* fin = inicio + 4;
    int* actual = inicio;
    int cantidad = 0;

    if (!(std::cin >> cantidad) || cantidad < 1 || cantidad > 12) {
        return 1;
    }
    for (int orden = 0; orden < cantidad; ++orden) {
        int operacion = 0;
        int argumento = 0;

        if (!(std::cin >> operacion >> argumento)) {
            return 1;
        }
        std::string estado = "Orden";
        if (operacion == 1) {
            estado = situar(actual, inicio, argumento) ? "Seleccion" : "Rechazo";
        } else if (operacion == 2) {
            estado = mover(actual, inicio, argumento) ? "Movimiento" : "Rechazo";
        } else if (operacion == 3) {
            estado = escribir(actual, fin, argumento);
        }
        std::cout << "Estado:" << estado << ";Pos:" << (actual - inicio) << ";Valor:";
        if (actual == fin) {
            std::cout << 'X';
        } else {
            std::cout << *actual;
        }
        std::cout << ";Datos:" << datos[0] << ',' << datos[1] << ',' << datos[2] << ',' << datos[3] << '\n';
    }

    return 0;
}

